        cmd("SendMessage", json!({"QueueName": "f.fifo", "Body": "x"})),
        cmd("SendMessage", json!({"QueueName": "f.fifo", "Body": "x", "GroupId": "g"})),
        cmd("SendMessage", json!({"QueueName": "c.fifo", "Body": "x", "GroupId": "g"})),
        fifo_send("f.fifo", "x", "g", "d"),
    ]);
    let results: Vec<_> = responses[2..].iter().map(outcome).collect();
    assert_eq!(
        results,
        ["UnsupportedOperation", "MissingParameter", "MissingParameter", "ok", "ok"]
    );
    assert_eq!(responses[5], json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(responses[6], json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 1}));
