        cmd("SendMessage", json!({"QueueName": "f.fifo", "Body": "x"})),
        cmd("SendMessage", json!({"QueueName": "f.fifo", "Body": "x", "GroupId": "g"})),
        cmd("SendMessage", json!({"QueueName": "c.fifo", "Body": "x", "GroupId": "g"})),
