        fifo_send("f.fifo", "other body", "other group", "d"),
        fifo_send("f.fifo", "b", "g", "e"),
        tick(1),
        // The duplicate at 299 did not extend the window: 300 is past it.
        fifo_send("f.fifo", "again", "g", "d"),
        fifo_send("f.fifo", "again", "g", "d"),
    ]);
    assert_eq!(responses[3], json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(responses[4], json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
    assert_eq!(responses[6], json!({"ok": true, "MessageId": "m-3", "SequenceNumber": 3}));
    assert_eq!(responses[7], responses[6]);
