    assert_eq!(bodies(&responses[10]), ["existing"]);
    // Both messages share group g, so the moved one waits behind the first.
    assert_eq!(
        responses[10]["Messages"][0]["SequenceNumber"],
        json!(1)
    );
    assert_eq!(bodies(&responses[11]), Vec::<&str>::new());
}

